INSERT INTO testimonials (name, location, content, product_id) VALUES ('Aisha K.', 'Lahore', 'The hibiscus shampoo completely transformed my dry, frizzy hair! It''s so much softer and manageable now. A must-try!', 'hibiscus-shampoo');
INSERT INTO testimonials (name, location, content, product_id) VALUES ('Bilal M.', 'Karachi', 'I''ve struggled with oily skin for years. The activated charcoal soap has been a game changer. My skin feels clean and balanced.', 'charcoal-soap');
INSERT INTO testimonials (name, location, content, product_id) VALUES ('Fatima R.', 'Islamabad', 'This is hands down the best organic hair oil I''ve used. My hair fall has significantly reduced in just a few weeks.', 'miracle-hair-oil');
INSERT INTO testimonials (name, location, content, product_id) VALUES ('Saad A.', 'Lahore', 'As someone with sensitive skin, finding a natural soap that doesn''t irritate is tough. The Neem soap is gentle yet effective.', 'charcoal-soap');
INSERT INTO testimonials (name, location, content, product_id) VALUES ('Zainab S.', 'Faisalabad', 'The rose glow soap is pure luxury! The scent is incredible and it leaves my skin feeling so soft and hydrated. It''s my daily aromatherapy.', 'lemon-tangerine-soap');
INSERT INTO testimonials (name, location, content, product_id) VALUES ('Omar F.', 'Rawalpindi', 'The coffee scrub soap is the perfect exfoliator. It''s invigorating in the morning and leaves my skin incredibly smooth.', 'charcoal-soap');
INSERT INTO testimonials (name, location, content, product_id) VALUES ('Hira T.', 'Multan', 'The Amla shampoo actually promotes new hair growth. I can see baby hairs after a month of use. So happy with this.', 'amla-reetha-shampoo');
INSERT INTO testimonials (name, location, content, product_id) VALUES ('Imran G.', 'Gujranwala', 'The sandalwood soap has such a calming, classic scent. A high-quality, made in Pakistan soap that I''m proud to use.', 'charcoal-soap');
INSERT INTO testimonials (name, location, content, product_id) VALUES ('Sana J.', 'Peshawar', 'My skin has never felt softer. The Ubtan soap gives a natural glow and smells heavenly. Absolutely recommended!', 'papaya-soap');
