INSERT INTO testimonials (name, location, content, product_id) VALUES ('Maryam N.', 'Sialkot', 'The Miracle Hair Oil truly lives up to its name. My hair is thicker, shinier, and feels so much healthier.', 'miracle-hair-oil');
